#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    string s;
    cin >> s;

    // Replace all occurrences of parentheses with underscores
    regex pattern("\\([a-zA-Z_]*\\)");
    string replacedString = regex_replace(s, pattern, "_");

    // Split the string by one or more underscores
    vector<string> segments;
    size_t start = 0, end;
    while ((end = replacedString.find('_', start)) != string::npos) {
        if (end != start) {
            segments.push_back(replacedString.substr(start, end - start));
        }
        start = end + 1;
    }
    if (start < replacedString.size()) {
        segments.push_back(replacedString.substr(start));
    }

    int maxSegmentLength = 0;
    for (const auto& segment : segments) {
        if ((int)segment.length() > maxSegmentLength) {
            maxSegmentLength = segment.length();
        }
    }
    cout << maxSegmentLength << "\n";

    int totalCount = 0;
    bool inParentheses = false;
    int startIdx = -1, endIdx = -1;
    for (int i = 0; i < (int)s.size(); i++) {
        char ch = s[i];
        if (ch == '(') {
            inParentheses = true;
            startIdx = i;
        } else if (ch == ')' && inParentheses) {
            inParentheses = false;
            endIdx = i;
            string inside = s.substr(startIdx + 1, endIdx - startIdx - 1);
            if (!inside.empty()) {
                // Split inside string by underscores
                vector<string> partsInside;
                size_t startInside = 0, endInside;
                while ((endInside = inside.find('_', startInside)) != string::npos) {
                    if (endInside != startInside) {
                        partsInside.push_back(inside.substr(startInside, endInside - startInside));
                    }
                    startInside = endInside + 1;
                }
                if (startInside < inside.size()) {
                    partsInside.push_back(inside.substr(startInside));
                }
                int countInside = (int)partsInside.size();
                if (!inside.empty() && inside[0] == '_') {
                    countInside -= 1;
                }
                totalCount += countInside;
            }
        }
    }
    cout << totalCount << "\n";

    return 0;
}
